const PART_A = {
  conditions: 3,                     // A: amount <= balance · B: isVip · C: dailyUsed + amount <= limit
  multipleConditionCombinations: 8,  // 2^3
  minMCDC: 4,                        // n + 1
  conditionNotDecision: [[true, true, false], [false, false, true]],  // each condition flips, decision False both times
};

// (A,B,C): (T,·,T)→OK · (F,F,·)→DENIED · (F,T,T)→OK · (T,·,F)→DENIED
const MCDC = [
  { id: 'M1', input: { balance: 5000000, amount: 1000000, dailyUsed: 0, isVip: false, isFrozen: false }, expected: 'OK' },
  { id: 'M2', input: { balance: 500000, amount: 1000000, dailyUsed: 0, isVip: false, isFrozen: false }, expected: 'DENIED' },
  { id: 'M3', input: { balance: 500000, amount: 1000000, dailyUsed: 0, isVip: true, isFrozen: false }, expected: 'OK' },
  { id: 'M4', input: { balance: 20000000, amount: 5000000, dailyUsed: 6000000, isVip: false, isFrozen: false }, expected: 'DENIED' },
];

// Given suite: 1 kg, 5 kg, 20 kg.
const PART_B = {
  killed: ['M3', 'M4', 'M8'],      // they change a value the suite checks
  equivalent: ['M7'],              // ceil(w − 2) = ceil(w) − 2 for every w
  score: 42.86,                    // 3 / (8 − 1) × 100
};

// Boundaries (2, 10, 0) and a non-integer weight kill the survivors M1, M2, M5, M6.
test.each([
  [1, 15000], [2, 15000],          // ≤ 2 kg, including the boundary
  [2.5, 25000], [5, 35000], [10, 60000],  // started kg above 2 (2.5 → 1 started kg), boundary 10
  [20, 70000],
])('shippingFee(%p) = %i', (w, fee) => {
  expect(shippingFee(w)).toBe(fee);
});
test('zero weight is rejected', () => {
  expect(() => shippingFee(0)).toThrow(RangeError);
});

